(() => {
  'use strict';

  const dialog   = document.getElementById('delete-dialog');
  const triggers = document.querySelectorAll('.trigger');
  const cancelBtn = document.getElementById('cancel-delete');
  const confirmBtn = document.getElementById('confirm-delete');

  // The element that opened the dialog — used to restore focus on close
  let openerElement = null;

  /** Open the dialog */
  function openDialog(triggerEl) {
    openerElement = triggerEl;
    dialog.showModal();
    // Move focus to the cancel (safe) action by default
    cancelBtn.focus();
  }

  /** Close the dialog and restore focus */
  function closeDialog() {
    dialog.close();
    if (openerElement) {
      openerElement.focus();
      openerElement = null;
    }
  }

  // Attach open handler to every trigger button
  triggers.forEach(btn => {
    btn.addEventListener('click', () => openDialog(btn));
  });

  // Cancel / close actions
  cancelBtn.addEventListener('click', closeDialog);

  // Clicking the backdrop (outside dialog-inner) closes the dialog
  dialog.addEventListener('click', (e) => {
    // e.target is the <dialog> element itself when clicking the backdrop
    if (e.target === dialog) closeDialog();
  });

  // Confirm delete — replace with real deletion logic as needed
  confirmBtn.addEventListener('click', () => {
    closeDialog();
    announceAction('Image deleted from your library.');
    // Optionally remove the card or redirect here
  });

  /** Politely announce a status message to screen readers */
  function announceAction(message) {
    const region = document.getElementById('live-region');
    region.textContent = '';
    // Tiny delay ensures AT picks up the change
    requestAnimationFrame(() => { region.textContent = message; });
  }
})();

